<?php include 'config.php'; $id=(int)($_GET['id']??0); $p=$conn->query("SELECT * FROM products WHERE product_id=$id")->fetch_assoc(); if(!$p)die('Not found'); ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Product</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'nav.php'; ?><section class="page"><div class="table-box" style="display:grid;grid-template-columns:1fr 1fr;gap:30px"><img src="<?=clean($p['image_url'])?>" style="width:100%;border-radius:22px"><div><h1><?=clean($p['name'])?></h1><p><?=clean($p['description'])?></p><p>Stock: <?=clean($p['stock_quantity'])?></p><p class="price">$<?=clean($p['price'])?></p><form action="add_to_cart.php" method="POST"><input type="hidden" name="product_id" value="<?=$p['product_id']?>"><input type="number" name="quantity" value="1" min="1"><button>Add to Cart</button></form></div></div></section></body></html>